func TestFitnessSeries(t *testing.T) {
	d0 := time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)
	loads := map[time.Time]float64{}
	for i := range 200 {
		loads[d0.AddDate(0, 0, i)] = 100
	}
	s := FitnessSeries(loads, d0.AddDate(0, 0, 209))
	if len(s) != 210 || !s[0].Date.Equal(d0) {
		t.Fatalf("days %d", len(s))
	}
	// First day: one step of each average.
	if math.Abs(s[0].Fitness-100*(1-math.Exp(-1.0/42))) > 1e-9 || s[0].Form != 0 {
		t.Errorf("day 1 %+v", s[0])
	}
	// After 200 days of constant load, fitness and fatigue converge to it.
	d := s[199]
	if math.Abs(d.Fitness-100) > 1 || math.Abs(d.Fatigue-100) > 1e-6 || math.Abs(d.ACWR-1) > 0.01 {
		t.Errorf("steady state %+v", d)
	}
	// Ten rest days: fatigue drops faster than fitness → positive form.
	last := s[209]
	if last.Load != 0 || last.Fatigue >= last.Fitness || last.Form <= 0 || last.ACWR >= 0.8 {
		t.Errorf("after rest %+v", last)
	}
	if FitnessSeries(nil, d0) != nil {
		t.Error("no loads")
	}
}

